delete from public.knowledge_docs where slug='prog-chem-biochem';
insert into public.knowledge_docs(slug,title,body) values ('prog-chem-biochem','برنامج الكيمياء والكيمياء الحيوية (من البروشور الرسمي للكلية)',$b$المصدر: بروشور/إنفوجرافيك رسمي للبرنامج مقدم من مؤسس المنصة، المعروض في صفحة البرنامج بالمنصة. لا تضف عليه شيئًا ولا تذكر رسومًا أو أرقام قبول أو أسماء أساتذة لأنها غير موجودة.
- البرنامج: الكيمياء والكيمياء الحيوية (Chemistry & Biochemistry)
- الدرجة: بكالوريوس العلوم في الكيمياء والكيمياء الحيوية
- الساعات المعتمدة: 138 ساعة معتمدة
- لغة الدراسة: الإنجليزية
- المدة: أربع سنوات دراسية (أربعة مستويات) — 8 فصول دراسية
- نبذة: الكيمياء والكيمياء الحيوية من التخصصات الأساسية في تطوير الأدوية والعلاجات والتشخيص الطبي، وتدخل في صناعات متعددة مثل الأغذية والمواد الكيميائية والبيئة. البرنامج يؤهلك لفهم وتطبيق التحليلات والتقنيات الحديثة المستخدمة في المجالات العلمية والصناعية والصحية.
- مجالات العمل بعد التخرج: مصانع الأدوية والصناعات الغذائية؛ مراقبة الجودة والتحاليل المعملية؛ التشخيص الطبي والمعامل الطبية؛ الصناعات الكيميائية والبتروكيماويات؛ البحث العلمي في الجامعات ومراكز البحوث؛ المجال البيئي ومعالجة الملوثات
- ماذا يكتسب الطالب / لماذا البرنامج: مهارات تحليلية وعملية باستخدام أحدث التقنيات؛ أساس قوي يؤهلك لمجالات متنوعة؛ فرص عمل في قطاعات مختلفة محلياً ودولياً
- غير مؤكد: المقررات التفصيلية والخطة الدراسية لهذا البرنامج، والمصروفات، وشروط القبول، لا توجد عندي من مصدر رسمي. إن سُئلت عنها قل إنها غير موثقة عندك ووجّه الطالب لإدارة الكلية.$b$);
delete from public.knowledge_docs where slug='prog-nuclear-physics';
insert into public.knowledge_docs(slug,title,body) values ('prog-nuclear-physics','برنامج الفيزياء النووية والمفاعلات (من البروشور الرسمي للكلية)',$b$المصدر: بروشور/إنفوجرافيك رسمي للبرنامج مقدم من مؤسس المنصة، المعروض في صفحة البرنامج بالمنصة. لا تضف عليه شيئًا ولا تذكر رسومًا أو أرقام قبول أو أسماء أساتذة لأنها غير موجودة.
- البرنامج: الفيزياء النووية والمفاعلات (Nuclear Physics & Reactors)
- الدرجة: بكالوريوس العلوم في الفيزياء النووية والمفاعلات
- الساعات المعتمدة: 138 ساعة معتمدة
- لغة الدراسة: الإنجليزية
- المدة: أربع سنوات دراسية (أربعة مستويات) — 8 فصول دراسية
- نبذة: مع توجه مصر نحو التوسع في الطاقة النووية ومشروع محطة الضبعة، يزداد الاهتمام بالكفاءات المتخصصة في الفيزياء النووية والمفاعلات. البرنامج يؤهلك لفهم وتطبيق علوم الطاقة النووية في مجالات حيوية مثل تشغيل المفاعلات والوقاية الإشعاعية والبحث العلمي، بما يدعم احتياجات الدولة والعالم في هذا القطاع.
- مجالات العمل بعد التخرج: محطات الطاقة النووية والمفاعلات؛ هيئات الرقابة والأمان النووي؛ تطبيقات الإشعاع في الطب والصناعة؛ البحث العلمي في الفيزياء النووية؛ الجامعات ومراكز البحوث؛ مجالات القياس والإشعاع والبيئة
- ماذا يكتسب الطالب / لماذا البرنامج: فرص عمل في مجالات متنوعة محليًا ودوليًا؛ مهارات في تشغيل الأنظمة النووية وتحليل البيانات؛ المساهمة في مشروعات قومية تدعم أمن الطاقة والتنمية
- غير مؤكد: المقررات التفصيلية والخطة الدراسية لهذا البرنامج، والمصروفات، وشروط القبول، لا توجد عندي من مصدر رسمي. إن سُئلت عنها قل إنها غير موثقة عندك ووجّه الطالب لإدارة الكلية.$b$);
