insert into public.knowledge_docs(slug,title,body) values ('prog-rad-physics','برنامج الفيزياء الإشعاعية والطبية (من البروشور الرسمي للكلية)',$b$المصدر: بروشور/إنفوجرافيك رسمي للبرنامج مقدم من مؤسس المنصة، المعروض في صفحة البرنامج بالمنصة. لا تضف عليه شيئًا ولا تذكر رسومًا أو أرقام قبول أو أسماء أساتذة لأنها غير موجودة.
- البرنامج: الفيزياء الإشعاعية والطبية (Radiation & Medical Physics)
- الدرجة: بكالوريوس العلوم في الفيزياء الإشعاعية والطبية
- الساعات المعتمدة: 138 ساعة معتمدة
- لغة الدراسة: الإنجليزية
- المدة: أربع سنوات دراسية (أربعة مستويات) — 8 فصول دراسية (وفصل صيفي إن وجد)
- نبذة: برنامج يركز على توظيف مبادئ الفيزياء في التطبيقات الإشعاعية والطبية، ومنها التصوير الطبي والعلاج الإشعاعي والطب النووي وفيزياء الصحة. يجمع الدراسة العلمية بالتدريب التطبيقي على الأجهزة والقياسات وضبط الجودة والسلامة الإشعاعية.
- الفيزياء في خدمة صحة الإنسان: يدرس البرنامج مبادئ الفيزياء وتطبيقاتها في التصوير الطبي والعلاج الإشعاعي والطب النووي، مع تدريب عملي على الأجهزة الحديثة، بما يساهم في دعم التشخيص والعلاج وضبط الجودة والسلامة الإشعاعية.
- مجالات العمل بعد التخرج: المستشفيات وأقسام التصوير الطبي والعلاج الإشعاعي والطب النووي؛ مراكز الأورام؛ مراكز البحوث؛ صناعة الأجهزة والمبيعات والدعم الفني والصيانة والتدريب؛ السلطات الرقابية؛ الوقاية الإشعاعية وضبط الجودة؛ التعليم؛ التطبيقات المرتبطة بتعدين اليورانيوم
- ماذا يكتسب الطالب / لماذا البرنامج: تركيز على السلامة الإشعاعية وجودة الأجهزة؛ تأهيل متخصص في التصوير الطبي والعلاج الإشعاعي والطب النووي؛ تدريب عملي داخل المعامل والمراكز الطبية؛ الاستفادة من التقنيات الحديثة في تحليل الصور الطبية
- غير مؤكد: المقررات التفصيلية والخطة الدراسية لهذا البرنامج، والمصروفات، وشروط القبول، لا توجد عندي من مصدر رسمي. إن سُئلت عنها قل إنها غير موثقة عندك ووجّه الطالب لإدارة الكلية.$b$);
