insert into public.knowledge_docs(slug,title,body) values ('prog-micro-biochem','برنامج الميكروبيولوجي والكيمياء الحيوية (من البروشور الرسمي للكلية)',$b$المصدر: بروشور/إنفوجرافيك رسمي للبرنامج مقدم من مؤسس المنصة، المعروض في صفحة البرنامج بالمنصة. لا تضف عليه شيئًا ولا تذكر رسومًا أو أرقام قبول أو أسماء أساتذة لأنها غير موجودة.
- البرنامج: الميكروبيولوجي والكيمياء الحيوية (Microbiology & Biochemistry)
- الدرجة: بكالوريوس العلوم في الميكروبيولوجي والكيمياء الحيوية
- الساعات المعتمدة: 138 ساعة معتمدة
- لغة الدراسة: الإنجليزية
- المدة: أربع سنوات دراسية (أربعة مستويات) — 8 فصول دراسية
- نبذة: مع التوسع في الصناعات الدوائية والغذائية، وزيادة الاهتمام بمراقبة جودة الغذاء والمياه ومكافحة الأمراض المعدية، أصبح هناك طلب متزايد على متخصصين في الميكروبيولوجي والكيمياء الحيوية للعمل في مجالات البحث والصناعة والرعاية الصحية والبيئة.
- مجالات العمل بعد التخرج: المعامل الطبية والبيولوجية؛ الصناعات الدوائية واللقاحات؛ الصناعات الغذائية ومراقبة الجودة؛ المختبرات البحثية ومراكز التطوير؛ المجالات البيئية ومعالجة الملوثات؛ التعليم والتدريب
- ماذا يكتسب الطالب / لماذا البرنامج: مهارات عملية في التحليل المجهري والتقنيات الحديثة؛ معرفة في العلوم الأساسية والتطبيقية للمجال؛ فرص عمل في قطاعات متنوعة محلياً ودولياً
- غير مؤكد: المقررات التفصيلية والخطة الدراسية لهذا البرنامج، والمصروفات، وشروط القبول، لا توجد عندي من مصدر رسمي. إن سُئلت عنها قل إنها غير موثقة عندك ووجّه الطالب لإدارة الكلية.$b$);
