insert into public.knowledge_docs(slug,title,body) values ('prog-smart-computing','برنامج بكالوريوس العلوم في الحوسبة الذكية (من البروشور الرسمي للكلية)',$b$المصدر: بروشور/إنفوجرافيك رسمي للبرنامج مقدم من مؤسس المنصة، المعروض في صفحة البرنامج بالمنصة. لا تضف عليه شيئًا ولا تذكر رسومًا أو أرقام قبول أو أسماء أساتذة لأنها غير موجودة.
- البرنامج: بكالوريوس العلوم في الحوسبة الذكية (Intelligent Computing)
- الدرجة: بكالوريوس العلوم في الحوسبة الذكية
- الساعات المعتمدة: 138 ساعة معتمدة
- لغة الدراسة: الإنجليزية
- المدة: أربع سنوات دراسية (أربعة مستويات) — 8 فصول دراسية
- نبذة: برنامج متعدد التخصصات يهدف إلى إعداد كوادر قادرة على تصميم وتطوير وتشغيل الأنظمة الذكية المعتمدة على الذكاء الاصطناعي وعلوم البيانات، والحوسبة السحابية وإنترنت الأشياء. يجمع بين علوم الحاسب والرياضيات التطبيقية والإحصاء والخوارزميات، مع تطبيقات عملية تدعم التحول الرقمي وخدمة المجتمع.
- مستقبل أكثر ذكاءً يبدأ من هنا: حوّل شغفك بالتقنية إلى إنجاز وكن صانع المستقبل — برنامج أكاديمي لمستقبل ذكي.
- مجالات العمل بعد التخرج: تطوير تطبيقات الذكاء الاصطناعي؛ تحليل البيانات وعلوم البيانات؛ الأمن السيبراني وحماية المعلومات؛ إنترنت الأشياء والأنظمة الذكية؛ تطوير البرمجيات والحلول التقنية؛ الشركات الناشئة التقنية (Startups)؛ مراكز الأبحاث والجامعات
- ماذا يكتسب الطالب / لماذا البرنامج: مجال متطور ومتعدد التخصصات؛ يتيح مسارات في الذكاء الاصطناعي والتقنيات الحديثة؛ يساهم في حلول واقعية لتحديات العالم؛ فرص عمل في مجالات متنوعة محلياً ودولياً
- غير مؤكد: المقررات التفصيلية والخطة الدراسية لهذا البرنامج، والمصروفات، وشروط القبول، لا توجد عندي من مصدر رسمي. إن سُئلت عنها قل إنها غير موثقة عندك ووجّه الطالب لإدارة الكلية.$b$);
